fm = parts[1]
m_name = re.search(r'^name:\s*(.+)$', fm, re.M)
m_desc = re.search(r"^description:\s*(?:'([^']*)'|\"([^\"]*)\"|(.+))$", fm, re.M)
if not m_name: errors.append('Missing name')
