# no TODO:
for f in sorted(root.rglob('*')):
    if f.is_file():
        t = f.read_text()
        if 'TODO:' in t: errors.append(f'TODO: found in {f}')

# static JS sanity: brace/paren/bracket/quote parity
js = (root / 'scripts' / 'slack_api.cjs').read_text()
for open_c, close_c in [('{','}'), ('(',')'), ('[',']')]:
