        errors.append(f'Unbalanced quote {q} in slack_api.cjs')

print('FILES:', [str(f.relative_to('.')) for f in sorted(root.rglob('*')) if f.is_file()])
if errors:
    print('VALIDATION FAILED:'); [print(' -', e) for e in errors]; raise SystemExit(1)
print('VALIDATION PASSED (mirrors validate_skill.cjs checks + static JS parity check)')
