#!/usr/bin/env node

/**
 * slack_api.cjs - Dependency-free Slack Web API helper.
 *
 * Requires Node.js 18+ (global fetch) and a Slack token in SLACK_TOKEN.
 * Outputs clean, LLM-friendly summaries plus JSON (truncated to 8000 chars).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node slack_api.cjs <operation> [args...] [options]
 *
 * Operations:
 *   post-message   <channel> <text> [--thread-ts <ts>] [--reply-broadcast]
 *   update-message <channel> <ts> <text>
 *   list-channels  [--limit N] [--exclude-archived]
 *   list-users     [--limit N]
 *   create-channel <name> [--private]
 *   get-history    <channel> [--limit N]
 *   get-thread     <channel> <thread-ts> [--limit N]
 *   channel-info   <channel-id>
 *   get-user       <user-id>
 *
 * <channel> may be a channel name (e.g. general) or ID (C123...).
 * Options must appear after positional args.
 */

const API_BASE = 'https://slack.com/api';
const MAX_OUTPUT = 8000;
const DEFAULT_LIMIT = 100;

function flagValue(args, flag) {
  const idx = args.indexOf(flag);
  if (idx === -1) return undefined;
  const value = args[idx + 1];
  if (value === undefined || value.startsWith('--')) {
    throw new Error(`Flag ${flag} requires a value`);
  }
  return value;
}

function hasFlag(args, flag) {
  return args.includes(flag);
}

function intValue(value, flag, fallback = DEFAULT_LIMIT) {
  if (value === undefined) return fallback;
  const n = Number.parseInt(value, 10);
  if (Number.isNaN(n) || n < 1) {
    throw new Error(`Invalid value for ${flag}: ${value}`);
  }
  return n;
}

async function apiCall(method, params = {}) {
  const token = process.env.SLACK_TOKEN;
  if (!token) throw new Error('SLACK_TOKEN environment variable is not set');

  const body = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== null && value !== '') {
      body.set(key, String(value));
    }
  }

  const res = await fetch(`${API_BASE}/${method}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body,
  });
  if (!res.ok) throw new Error(`HTTP ${res.status} from Slack API`);

  const data = await res.json();
  if (!data.ok) throw new Error(`Slack API error: ${data.error}`);
  return data;
}

function truncate(text, max = MAX_OUTPUT) {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}\n... [truncated: ${text.length - max} more chars]`;
}

function json(value) {
  return JSON.stringify(value, null, 2);
}

function printSuccess(summary, payload) {
  process.stdout.write(`Success: ${summary}\n`);
  process.stdout.write(`${truncate(json(payload))}\n`);
}

function channelSummary(channel) {
  return {
    id: channel.id,
    name: channel.name,
    is_private: channel.is_private,
    is_archived: channel.is_archived,
    is_member: channel.is_member,
    num_members: channel.num_members,
  };
}

function userSummary(user) {
  return {
    id: user.id,
    name: user.name,
    real_name: user.real_name,
    display_name: user.profile ? user.profile.display_name : undefined,
    email: user.profile ? user.profile.email : undefined,
    is_bot: user.is_bot,
    is_restricted: user.is_restricted,
    deleted: user.deleted,
  };
}

function messageSummary(message) {
  return {
    ts: message.ts,
    user: message.user,
    subtype: message.subtype,
    text: message.text,
    reply_count: message.reply_count,
  };
}

async function main() {
  const args = process.argv.slice(2);
  const op = args[0];

  if (!op || op === '--help' || op === '-h') {
    process.stdout.write(`Slack API helper
Usage: SLACK_TOKEN=xoxb-... node slack_api.cjs <operation> [args...]

Operations:
  post-message   <channel> <text> [--thread-ts <ts>] [--reply-broadcast]
  update-message <channel> <ts> <text>
  list-channels  [--limit N] [--exclude-archived]
  list-users     [--limit N]
  create-channel <name> [--private]
  get-history    <channel> [--limit N]
  get-thread     <channel> <thread-ts> [--limit N]
  channel-info   <channel-id>
  get-user       <user-id>

<channel> may be a name (general) or ID (C123...). Options go after positional args.
`);
    return;
  }

  switch (op) {
    case 'post-message': {
      const channel = args[1];
      const text = args[2];
      const threadTs = flagValue(args, '--thread-ts');
      const replyBroadcast = hasFlag(args, '--reply-broadcast');
      if (!channel || text === undefined) {
        throw new Error(
          'Usage: post-message <channel> <text> [--thread-ts <ts>] [--reply-broadcast]',
        );
      }
      const data = await apiCall('chat.postMessage', {
        channel,
        text,
        thread_ts: threadTs,
        reply_broadcast: replyBroadcast || undefined,
      });
      const where = threadTs ? ` in thread ${threadTs}` : '';
      printSuccess(
        `Message posted to ${data.channel} (ts: ${data.ts})${where}`,
        data.message || data,
      );
      break;
    }

    case 'update-message': {
      const channel = args[1];
      const ts = args[2];
      const text = args[3];
      if (!channel || !ts || text === undefined) {
        throw new Error('Usage: update-message <channel> <ts> <text>');
      }
      const data = await apiCall('chat.update', { channel, ts, text });
      printSuccess(
        `Message ${ts} updated in ${data.channel}`,
        data.message || data,
      );
      break;
    }

    case 'list-channels': {
      const limit = intValue(flagValue(args, '--limit'), '--limit');
      const excludeArchived = hasFlag(args, '--exclude-archived');
      const data = await apiCall('conversations.list', {
        types: 'public_channel,private_channel',
        limit,
        exclude_archived: excludeArchived || undefined,
      });
      const channels = (data.channels || []).map(channelSummary);
      const cursor = data.response_metadata
        ? data.response_metadata.next_cursor
        : undefined;
      printSuccess(
        `Found ${channels.length} channels${cursor ? ' (more pages available)' : ''}`,
        { channels, next_cursor: cursor },
      );
      break;
    }

    case 'list-users': {
      const limit = intValue(flagValue(args, '--limit'), '--limit');
      const data = await apiCall('users.list', { limit });
      const users = (data.members || []).map(userSummary);
      const cursor = data.response_metadata
        ? data.response_metadata.next_cursor
        : undefined;
      printSuccess(
        `Found ${users.length} users${cursor ? ' (more pages available)' : ''}`,
        { users, next_cursor: cursor },
      );
      break;
    }

    case 'create-channel': {
      const name = args[1];
      const isPrivate = hasFlag(args, '--private');
      if (!name) throw new Error('Usage: create-channel <name> [--private]');
      const data = await apiCall('conversations.create', {
        name,
        is_private: isPrivate || undefined,
      });
      printSuccess(
        `Channel created: #${data.channel.name} (${data.channel.id})`,
        channelSummary(data.channel),
      );
      break;
    }

    case 'get-history': {
      const channel = args[1];
      const limit = intValue(flagValue(args, '--limit'), '--limit');
      if (!channel) throw new Error('Usage: get-history <channel> [--limit N]');
      const data = await apiCall('conversations.history', { channel, limit });
      const messages = (data.messages || []).map(messageSummary);
      const cursor = data.response_metadata
        ? data.response_metadata.next_cursor
        : undefined;
      printSuccess(
        `Fetched ${messages.length} messages from ${channel}${cursor ? ' (more pages available)' : ''}`,
        { messages, next_cursor: cursor },
      );
      break;
    }

    case 'get-thread': {
      const channel = args[1];
      const threadTs = args[2];
      const limit = intValue(flagValue(args, '--limit'), '--limit');
      if (!channel || !threadTs) {
        throw new Error('Usage: get-thread <channel> <thread-ts> [--limit N]');
      }
      const data = await apiCall('conversations.replies', {
        channel,
        ts: threadTs,
        limit,
      });
      const messages = (data.messages || []).map(messageSummary);
      printSuccess(
        `Fetched ${messages.length} messages in thread ${threadTs}`,
        { messages },
      );
      break;
    }

    case 'channel-info': {
      const channel = args[1];
      if (!channel) throw new Error('Usage: channel-info <channel-id>');
      const data = await apiCall('conversations.info', { channel });
      printSuccess(
        `Channel info: #${data.channel.name}`,
        channelSummary(data.channel),
      );
      break;
    }

    case 'get-user': {
      const user = args[1];
      if (!user) throw new Error('Usage: get-user <user-id>');
      const data = await apiCall('users.info', { user });
      printSuccess(`User info: ${data.user.name}`, userSummary(data.user));
      break;
    }

    default:
      throw new Error(`Unknown operation: ${op}. Run with --help for usage.`);
  }
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

